public:
	explicit buffer_adaptor(buf_type& buffer)
		: buffer_read_adaptor<buf_type>(buffer),
		  buffer_write_adaptor<buf_type>(buffer) {}

	explicit buffer_adaptor(buf_type& buffer, init_empty_t)
