PacketHeader read_packet_header(const std::span<const uint8_t> buffer) {
    // Wrap the incoming span in a Hexi buffer adaptor and binary_stream.
    // This allows us to use stream.span() for a zero-copy view,
    // and then reinterpret that view as a PacketHeader.
    using Vec = std::basic_string_view<uint8_t>;
    Vec view(buffer.data(), buffer.size());
    hexi::buffer_adaptor<Vec, false> adaptor(view);
    hexi::binary_stream stream(adaptor);

    // Request a span over the header-sized region.
    auto header_span = stream.span<uint8_t>(sizeof(PacketHeader));
    PacketHeader header{};

    if(header_span.size() == sizeof(PacketHeader)) {
        // Zero-copy reinterpretation of the span as a PacketHeader.
        const auto* ptr = reinterpret_cast<const PacketHeader*>(header_span.data());
        header = *ptr;
    }

    return header;
}

