struct DataResult {
    uint8_t data_type;
    std::vector<uint32_t> int_items;
    std::vector<float> float_items;
};

DataResult preview_and_read_data(const std::span<const uint8_t> buffer) {
    DataResult result{};
    result.data_type = 0;

    // Wrap the input span in a mutable container so Hexi's adaptors can work
    // (they expect a non-const, contiguous byte-oriented range).
    std::vector<std::uint8_t> storage(buffer.begin(), buffer.end());

    // Create a buffer adaptor over the storage
    hexi::buffer_adaptor<std::vector<std::uint8_t>> adaptor(storage);

    // Preview the first byte (data_type) without advancing the read pointer.
    // buffer_adaptor::copy(...) does not move the read cursor.
    if (adaptor.size() < sizeof(std::uint8_t)) {
        // Not enough data even for the header; leave result default-initialised.
        return result;
    }

    std::uint8_t preview_type = 0;
    adaptor.copy(&preview_type);
    result.data_type = preview_type;

    // Check that we have at least enough data for data_type + item_count.
    if (adaptor.size() < sizeof(std::uint8_t) + sizeof(std::uint32_t)) {
        // Incomplete header; return with just the previewed type.
        return result;
    }

    // Now create a binary_stream on top of the same adaptor to actually read data.
    hexi::binary_stream<decltype(adaptor)> stream(adaptor);

    // Read header fields
    std::uint8_t data_type = 0;
    std::uint32_t item_count = 0;

    stream >> data_type;
    stream >> item_count;

    // Verify that the buffer has enough remaining bytes for all items of the
    // indicated type before attempting to read them.
    const std::size_t item_size = (data_type == 0) ? sizeof(std::uint32_t)
                                                   : sizeof(float);
    const std::size_t required_bytes =
        static_cast<std::size_t>(item_count) * item_size;

    if (stream.read_max() < required_bytes) {
        // Not enough data; return header info only.
        result.data_type = data_type;
        return result;
    }

    // Read items according to type
    if (data_type == 0) { // integers
        result.int_items.resize(item_count);
        stream.get(result.int_items.data(), item_count);
    } else if (data_type == 1) { // floats
        result.float_items.resize(item_count);
        stream.get(result.float_items.data(), item_count);
    } else {
        // Unknown data type; just propagate the type and leave vectors empty.
    }

    result.data_type = data_type;
    return result;
}
