bool write_data_with_check(std::vector<uint8_t>& buffer, uint32_t header, const std::vector<uint32_t>& items) {
    using hexi::buffer_adaptor;
    using hexi::binary_stream;

    // Wrap the existing buffer without resetting it (we assume existing data is valid)
    buffer_adaptor<std::vector<uint8_t>, true> adaptor(buffer);

    // Calculate required size:
    // - header: 4 bytes (uint32_t)
    // - items: items.size() * sizeof(uint32_t) bytes (using write_container, no prefix)
