        sizeof(uint32_t) + items.size() * sizeof(uint32_t);

    // Check available free space in the underlying storage
    if (adaptor.free() < required) {
        return false; // insufficient space
    }

    // Get the write pointer (not strictly needed for the write itself, but per requirements)
    auto* write_ptr = adaptor.write_ptr();
    (void)write_ptr; // suppress unused variable warning

    // Perform the actual write using Hexi's binary_stream
    binary_stream<buffer_adaptor<std::vector<uint8_t>, true>> stream(adaptor);

    // Write header
    stream << header;

    // Write container data (no length prefix, uses write_container)
    stream << items;

    // If the stream encountered a write error, report failure
    return stream.good();
