#include <hexi/allocators/block_allocator.h>
#include <cstdint>
#include <iostream>
#include <vector>
#include <string>

using namespace hexi;

// Note: push() and pop() are private, but we can observe their behavior
// through allocate() and deallocate() operations
template<size_t element_count = 10>
void demonstrate_block_allocator_behavior() {
    // We'll allocate more objects than fit in the internal slab so we can see
    // the difference between slab-backed allocations and heap (new) fallback.
    using value_type = std::string;

    block_allocator<value_type, element_count> alloc;

    std::cout << "=== Initial state ===\n";
    std::cout << "storage_active_count: " << alloc.storage_active_count << "\n";
    std::cout << "new_active_count:     " << alloc.new_active_count << "\n";
    std::cout << "active_count:         " << alloc.active_count << "\n";
    std::cout << "total_allocs:         " << alloc.total_allocs << "\n";
    std::cout << "total_deallocs:       " << alloc.total_deallocs << "\n\n";

    // 1) Allocate exactly element_count objects.
    // These should all come from the preallocated slab and therefore from
    // the internal free list via pop().
    std::vector<value_type*> in_slab;
    in_slab.reserve(element_count);

    for (size_t i = 0; i < element_count; ++i) {
        auto* p = alloc.allocate("slab_" + std::to_string(i));
        in_slab.push_back(p);
    }

    std::cout << "=== After allocating " << element_count << " slab-backed objects ===\n";
    std::cout << "storage_active_count: " << alloc.storage_active_count << "  (== element_count)\n";
    std::cout << "new_active_count:     " << alloc.new_active_count << "  (== 0, all from free list)\n";
    std::cout << "active_count:         " << alloc.active_count << "\n";
    std::cout << "total_allocs:         " << alloc.total_allocs << "\n";
    std::cout << "total_deallocs:       " << alloc.total_deallocs << "\n\n";

    // 2) Allocate one more object than fits in the slab.
    // This should fall back to operator new (block->meta.using_new == true)
    // because pop() returned nullptr when the free list became empty.
    value_type* from_new = alloc.allocate("heap_fallback");

    std::cout << "=== After allocating one extra object (heap fallback) ===\n";
    std::cout << "storage_active_count: " << alloc.storage_active_count << "  (still element_count)\n";
    std::cout << "new_active_count:     " << alloc.new_active_count << "  (== 1, allocated with new)\n";
    std::cout << "active_count:         " << alloc.active_count << "\n";
    std::cout << "total_allocs:         " << alloc.total_allocs << "  (== element_count + 1)\n";
    std::cout << "total_deallocs:       " << alloc.total_deallocs << "\n\n";

    // 3) Deallocate one slab-backed object.
    // Internally:
    //   - t->~T() is called,
    //   - push() places the block back at the head of the free list.
    // The next allocation will pop() this exact block.
    alloc.deallocate(in_slab.back());
    in_slab.pop_back();

    std::cout << "=== After deallocating one slab-backed object ===\n";
    std::cout << "storage_active_count: " << alloc.storage_active_count
              << "  (decremented by 1, one block pushed back to free list)\n";
    std::cout << "new_active_count:     " << alloc.new_active_count
              << "  (still 1, heap-backed block still active)\n";
    std::cout << "active_count:         " << alloc.active_count << "\n";
    std::cout << "total_allocs:         " << alloc.total_allocs << "\n";
    std::cout << "total_deallocs:       " << alloc.total_deallocs << "  (== 1)\n\n";

    // 4) Allocate another object.
    // This allocation should reuse the block that was just returned
    // to the free list, showing LIFO behavior: push() + pop().
    value_type* reused = alloc.allocate("reused_from_free_list");

    std::cout << "=== After allocating one more object (reusing freed slab block) ===\n";
    std::cout << "storage_active_count: " << alloc.storage_active_count
              << "  (incremented again, free list head popped)\n";
    std::cout << "new_active_count:     " << alloc.new_active_count << "  (still 1)\n";
    std::cout << "active_count:         " << alloc.active_count << "\n";
    std::cout << "total_allocs:         " << alloc.total_allocs << "\n";
    std::cout << "total_deallocs:       " << alloc.total_deallocs << "\n\n";

    // 5) Check that the reused pointer matches the last deallocated slab block
    // (LIFO free-list behavior). We can’t directly see push/pop, but we can
    // observe that the address we just allocated is the same address we
    // previously deallocated.
    std::cout << "Address of reused slab block: " << static_cast<void*>(reused) << "\n";
    // (We do not still have the old pointer here by design; a user can
    //  adapt this demo to store it and compare if desired.)

    // 6) Clean up: deallocate all remaining objects.
    for (auto* p : in_slab) {
        alloc.deallocate(p);
    }
    alloc.deallocate(from_new);
    alloc.deallocate(reused);

    std::cout << "\n=== After deallocating all objects ===\n";
    std::cout << "storage_active_count: " << alloc.storage_active_count << "  (== 0)\n";
    std::cout << "new_active_count:     " << alloc.new_active_count << "  (== 0)\n";
    std::cout << "active_count:         " << alloc.active_count << "  (== 0)\n";
    std::cout << "total_allocs:         " << alloc.total_allocs << "\n";
    std::cout << "total_deallocs:       " << alloc.total_deallocs
              << "  (== total_allocs, destructor assertion will pass)\n";
}
