template<size_t block_size = 1024>
std::vector<uint8_t> preview_data_without_consuming(
    const hexi::detail::intrusive_storage<block_size>& storage,
    size_t bytes_to_preview
) {
    // Determine how many bytes are actually readable
    const std::size_t available = storage.size();
    const std::size_t to_copy   = std::min(available, bytes_to_preview);

    std::vector<uint8_t> result(to_copy);

    if (to_copy > 0) {
