std::vector<uint8_t> read_file_data(const std::filesystem::path& file_path, size_t bytes_to_read) {
    hexi::file_buffer fb(file_path);
    if(!fb || bytes_to_read == 0) {
        return {};
    }

    // Limit to available readable data
    const auto available = fb.size();
    if(available == 0) {
        return {};
    }

    const auto to_read = static_cast<hexi::file_buffer::size_type>(
        std::min<std::size_t>(bytes_to_read, available)
    );

    std::vector<uint8_t> buffer(to_read);
    fb.read(buffer.data(), to_read);

    if(!fb) {
        // On error, return empty vector
        return {};
    }

    return buffer;
}

