template<size_t buffer_size = 1024>
void write_data_to_buffer(hexi::static_buffer<std::byte, buffer_size>& buffer,
                          const std::vector<uint8_t>& data) {
    // Determine how many bytes can actually be written without overflowing
    const auto bytes_available = buffer.free();
    const auto bytes_to_write  = std::min<std::size_t>(bytes_available, data.size());

    if (bytes_to_write == 0) {
        return; // nothing can be written
    }

    // static_buffer stores std::byte; reinterpret the source data as bytes
    buffer.write(static_cast<const void*>(data.data()), bytes_to_write);
}

