    // Clamp requested size to what is actually available
    const auto bytes_available = buffer.size();
    const auto bytes_to_read_clamped = std::min<std::size_t>(bytes_available, bytes_to_read);

    std::vector<uint8_t> result(bytes_to_read_clamped);
    if (bytes_to_read_clamped == 0) {
        return result; // empty vector
    }

    buffer.read(static_cast<void*>(result.data()), bytes_to_read_clamped);
    return result;
