		if constexpr(memcpy_write<container_type, binary_stream_writer>) {
			const auto bytes = container.size() * sizeof(cvalue_type);
			write(container.data(), bytes);
		} else {
			for(auto& element : container) {
				*this << element;
			}
		}
	}

