using namespace hexi::detail;

template<typename T>
std::size_t encode_varint(hexi::pmc::binary_stream_writer& writer, T value) {
	static_assert(std::is_unsigned_v<T>, "encode_varint requires an unsigned integer type");

	std::size_t bytes_written = 0;

	// Standard LEB128-style varint: 7 bits per byte, MSB = continuation flag.
	while(true) {
		std::uint8_t byte = static_cast<std::uint8_t>(value & 0x7F);
		value >>= 7;

		if(value != 0) {
			byte |= 0x80; // set continuation bit
		}

		writer.put(byte);
		++bytes_written;

		if(value == 0) {
			break;
		}
	}

	return bytes_written;
}

template<typename T>
T decode_varint(hexi::pmc::binary_stream_reader& reader) {
	static_assert(std::is_unsigned_v<T>, "decode_varint requires an unsigned integer type");

	T result = 0;
	std::size_t shift = 0;

	while(true) {
		std::uint8_t byte = reader.get<std::uint8_t>();

		// If a read error occurred, or we've already filled the type, set error and return 0.
		if(reader.state() != hexi::detail::stream_state::ok || shift >= sizeof(T) * 8) {
			reader.set_error_state();
			return 0;
		}

		result |= static_cast<T>(byte & 0x7F) << shift;
		shift += 7;

		if((byte & 0x80) == 0) {
			break;
		}
	}

	return result;
}

template<typename T>
bool encode_decode_roundtrip(T original_value) {
	static_assert(std::is_unsigned_v<T>, "encode_decode_roundtrip requires an unsigned integer type");

	using Byte = std::byte;
	std::vector<Byte> buffer;

	// Set up Hexi PMC buffer adaptor and writer
	hexi::pmc::buffer_adaptor<std::vector<Byte>> buf_adaptor(buffer, hexi::detail::init_empty);
	hexi::pmc::binary_stream_writer writer(buf_adaptor, hexi::detail::no_throw);

	encode_varint(writer, original_value);

	// Prepare reader over the same buffer
	hexi::pmc::binary_stream_reader reader(buf_adaptor, hexi::detail::no_throw);

	T decoded = decode_varint<T>(reader);

	return (reader.state() == hexi::detail::stream_state::ok) && decoded == original_value;
}
