#include <vector>
#include <cstdint>

struct ReadLimitInfo {
    std::size_t read_size;
    std::size_t total_read;
    std::size_t read_limit;
    bool occurred;
};

ReadLimitInfo catch_stream_read_limit() {
    ReadLimitInfo info{0, 0, 0, false};

    try {
        // Prepare a small buffer and wrap it in a Hexi PMC buffer_adaptor
        std::vector<std::byte> storage(8);
        hexi::pmc::buffer_adaptor<std::vector<std::byte>> adaptor(storage);

        // Create a binary_stream with a strict read limit
        // Use the throwing variant (default) so that exceeding the limit raises stream_read_limit
        hexi::pmc::binary_stream stream(adaptor, /*read_limit=*/4);

        // Write more data than the read limit, then attempt to read it back
        std::uint64_t value = 0x1122334455667788ULL;
        stream.write(&value, sizeof(value)); // write 8 bytes into the buffer

        // Now attempt to read 8 bytes while the read limit is only 4
        std::uint64_t dest{};
        stream.read(&dest, sizeof(dest));
    } catch (const hexi::stream_read_limit& ex) {
        info.read_size  = ex.read_size;
        info.total_read = ex.total_read;
        info.read_limit = ex.read_limit;
        info.occurred   = true;
    }

    return info;
}

ReadLimitInfo safe_read_with_limit_check(hexi::pmc::binary_stream& stream,
                                         void* destination,
                                         std::size_t length) {
    ReadLimitInfo info{0, 0, 0, false};

    try {
        stream.read(destination, length);
    } catch (const hexi::stream_read_limit& ex) {
        info.read_size  = ex.read_size;
        info.total_read = ex.total_read;
        info.read_limit = ex.read_limit;
        info.occurred   = true;
    }

    return info;
}
