	}

	/**
	 * @brief The amount of space left in the container.
	 * 
	 * @return The number of free bytes.
	 */
	auto free() const {
		return buffer_.size() - write_;
	}

	/*
	 * @brief Resets both the read and write cursors back to the beginning
