std::vector<uint8_t> serialize_compact_packet(const CompactPacket& packet) {
    // Use Hexi's buffer_adaptor over a std::vector<uint8_t>
    std::vector<std::uint8_t> buffer;
    hexi::buffer_adaptor<std::vector<std::uint8_t>> buf_adaptor(buffer, hexi::init_empty);

    // pmc::binary_stream gives us the put/varint/prefixed_varint API
    hexi::pmc::binary_stream stream(buf_adaptor);

    // packet_id is a simple uint32_t, use fixed 4-byte storage
    stream << packet.packet_id;

    // tags: vector<string> with a varint prefix for the element count
    stream << hexi::prefixed_varint(packet.tags);

    // data: string with a varint prefix for size
    stream << hexi::prefixed_varint(packet.data);

    return buffer;
}

CompactPacket deserialize_compact_packet(const std::span<const uint8_t> buffer) {
