std::vector<uint8_t> serialize_with_padding(const PaddedData& packet) {
    // Use a std::vector<uint8_t> as the underlying buffer for Hexi
    std::vector<uint8_t> buffer;

    // Create a buffer adaptor starting from an empty buffer
    hexi::buffer_adaptor<std::vector<uint8_t>> adaptor(buffer, hexi::init_empty);

    // Create a binary_stream over the adaptor
    hexi::binary_stream stream(adaptor);

    // Write header (uint16_t in native-endian storage)
    stream << packet.header;

    // Write data as a length-prefixed string
    stream << packet.data;

    // Write 16 bytes of padding with value 0x00
    stream.fill<16>(0x00);

    // Write footer (uint32_t in native-endian storage)
    stream << packet.footer;

    return buffer;
}
