    // but write_adaptor will resize as needed).
    std::size_t available = writer.free();
    (void)available; // suppress unused warning; here just to demonstrate free()

    // Write the entire input_data into the buffer.
    // We use the pointer+length overload of write().
    if (!input_data.empty()) {
        writer.write(static_cast<const void*>(input_data.data()), input_data.size());
    }

    // Now read the data back using a read adaptor.
    hexi::pmc::buffer_read_adaptor<std::vector<uint8_t>> reader(buffer);

    // Use size() to know how many bytes are available to read.
    std::size_t readable = reader.size();

    std::vector<uint8_t> output(readable);
    if (readable > 0) {
        reader.read(static_cast<void*>(output.data()), readable);
    }

