#include <hexi/pmc/buffer_read_adaptor.h>
#include <hexi/pmc/buffer_write_adaptor.h>
#include <vector>
#include <cstdint>
#include <algorithm>

std::size_t write_multiple_chunks(const std::vector<std::vector<uint8_t>>& chunks) {
    // Start with an empty buffer and construct a write adaptor on top of it.
    std::vector<uint8_t> buffer;
    hexi::pmc::buffer_write_adaptor<std::vector<uint8_t>> writer(buffer, hexi::detail::init_empty);

    for (const auto& chunk : chunks) {
        // Ensure there is enough free space before each write.
        // If not, reserve additional space in the underlying vector.
        if (writer.free() < chunk.size()) {
            // Reserve current size + chunk size + some slack to reduce reallocations.
            buffer.reserve(buffer.size() + chunk.size());
        }

        writer.write(chunk.data(), chunk.size());
    }

    // The final buffer size corresponds to the total number of bytes written.
    return buffer.size();
}

std::vector<uint8_t> read_partial_data(const std::vector<uint8_t>& buffer, std::size_t chunk_size) {
    // Create a read adaptor over the provided buffer.
    hexi::pmc::buffer_read_adaptor<const std::vector<uint8_t>> reader(buffer);

    std::vector<uint8_t> result;
    result.reserve(buffer.size());

    while (!reader.empty()) {
        // Determine how much to read this iteration.
        std::size_t remaining = reader.size();
        std::size_t to_read   = std::min(chunk_size, remaining);

        std::vector<uint8_t> temp(to_read);
        reader.read(temp.data(), to_read);

        // Track what was read.
        result.insert(result.end(), temp.begin(), temp.end());

        // reader.size() is implicitly updated by reader.read()
        // and is used in the next iteration.
    }

    return result;
}
