struct ProtocolPacket {
    uint32_t message_id;
    std::vector<uint16_t> data_values;
    uint32_t checksum;
};

std::vector<uint8_t> serialize_protocol_packet(const ProtocolPacket& packet) {
    using namespace hexi;
    using namespace hexi::endian;

    std::vector<uint8_t> buffer;
    buffer.reserve(sizeof(uint32_t) * 3 + packet.data_values.size() * sizeof(uint16_t));

    // Use pmc buffer + stream so we can use write/write_container directly
    pmc::buffer pmc_buf;
    pmc::binary_stream_writer stream(pmc_buf);

    // message_id (uint32_t) -> big endian
    uint32_t msg_be = native_to_big(packet.message_id);
    stream.put(&msg_be, 1);

    // data_values count (uint32_t) in big endian
    uint32_t count = static_cast<uint32_t>(packet.data_values.size());
    uint32_t count_be = native_to_big(count);
    stream.put(&count_be, 1);

    // data_values elements: convert each uint16_t to big endian, then write_container
    std::vector<uint16_t> data_be;
    data_be.reserve(packet.data_values.size());
    for (uint16_t v : packet.data_values) {
        data_be.push_back(native_to_big(v));
    }
    stream.put(data_be.data(), data_be.size());

    // checksum (uint32_t) -> big endian
    uint32_t checksum_be = native_to_big(packet.checksum);
    stream.put(&checksum_be, 1);

    // Copy out from pmc buffer to std::vector<uint8_t>
    auto* pmc_read = static_cast<const hexi::pmc::buffer_read*>(stream.buffer());
    buffer.resize(pmc_read->size());
    pmc_read->peek(buffer.data(), buffer.size()); // assuming peek exists; if not, read_ptr/size
    return buffer;
}

ProtocolPacket deserialize_protocol_packet(const std::span<const uint8_t> buffer) {
    using namespace hexi;
    using namespace hexi::endian;

    ProtocolPacket packet{};

    // Wrap input span in a byte-oriented buffer adaptor
    pmc::buffer_read_view src(buffer.data(), buffer.size());
    pmc::binary_stream_reader stream(src);

    // message_id
    uint32_t msg_be = 0;
    stream.get(&msg_be, 1);
    packet.message_id = big_to_native(msg_be);

    // data_values count
    uint32_t count_be = 0;
    stream.get(&count_be, 1);
    uint32_t count = big_to_native(count_be);

    // data_values vector
    packet.data_values.resize(count);
    if (count > 0) {
        stream.get(packet.data_values.data(), count);
        for (auto& v : packet.data_values) {
            v = big_to_native(v);
        }
    }

    // checksum
    uint32_t checksum_be = 0;
    stream.get(&checksum_be, 1);
    packet.checksum = big_to_native(checksum_be);

    return packet;
}

struct ProtocolHeader {
    uint32_t message_id;
};

ProtocolHeader extract_protocol_header(const std::span<const uint8_t> buffer) {
    using namespace hexi;
    using namespace hexi::endian;

    ProtocolHeader header{};

    // Wrap input span in a byte-oriented buffer adaptor
    pmc::buffer_read_view src(buffer.data(), buffer.size());
    pmc::binary_stream_reader stream(src);

    // Get zero-copy span over first 4 bytes (message_id)
    auto id_span = stream.span<std::byte>(sizeof(uint32_t));
    if (id_span.size() < sizeof(uint32_t)) {
        return header; // or handle error
    }

    uint32_t msg_be = 0;
    std::memcpy(&msg_be, id_span.data(), sizeof(uint32_t));
    header.message_id = big_to_native(msg_be);

    // Advance past the header is already done by span(); if we needed more:
    // stream.skip(0); // no-op here

    return header;
}
