using hexi::endian::conditional_reverse;
using hexi::endian::little_to_native_inplace;

struct MeasurementData {
    uint32_t sensor_id;
    std::vector<float> temperatures;
    double pressure;

    // Serialisation (writing)
    void serialise(auto& adaptor) const {
        // Write sensor_id directly in native endianness
        adaptor.stream.put(sensor_id);

        // Write number of temperatures as uint32_t, little-endian
        uint32_t count = static_cast<uint32_t>(temperatures.size());
        auto count_le = conditional_reverse(count, std::endian::native, std::endian::little);
        adaptor.stream.put(count_le);

        // Write each temperature converted from native to little-endian
        for (float temp : temperatures) {
            float temp_le = conditional_reverse(temp, std::endian::native, std::endian::little);
            adaptor.stream.put(temp_le);
        }

        // Write pressure converted from native to little-endian
        double pressure_le = conditional_reverse(pressure, std::endian::native, std::endian::little);
        adaptor.stream.put(pressure_le);
    }

    // Deserialisation (reading)
    void serialise(auto& adaptor) {
